% ===== 离散LQR值函数曲面与山谷线可视化（扩展版） =====
clear; clc; close all;

% 系统参数（一维系统示例）
A = 0.8;        % 系统矩阵 
B = 1;          % 控制矩阵 
Q = 1;          % 状态权重 
R = 1;          % 控制权重 
x0 = 5;         % 初始状态 
N = 10;         % 总时间步长 

% === 1. 逆向递推求解P_k（动态规划核心） ===
P = zeros(1, N+1);  % 初始化P_k序列
P(N+1) = Q;         % 终端条件P_N=Q_N

% Riccati逆向递推
K_opt = zeros(1, N);  % 存储最优控制增益
for k = N:-1:1
    K_opt(k) = (R + B'*P(k+1)*B) \ (B'*P(k+1)*A);  % 时变增益
    P(k) = Q + A'*P(k+1)*A - A'*P(k+1)*B*K_opt(k); % Riccati方程
end

% === 2. 前向仿真计算最优轨迹 ===
x_opt = zeros(1, N+1);
u_opt = zeros(1, N);
x_opt(1) = x0;

for k = 1:N
    u_opt(k) = -K_opt(k) * x_opt(k);
    if k < N
        x_opt(k+1) = A * x_opt(k) + B * u_opt(k);
    end
end

% === 3. 创建状态-时间网格 ===
x_range = linspace(-10, 10, 50);   % 状态范围
k_range = 1:N;                     % 时间步范围
[X, K] = meshgrid(x_range, k_range);

% === 4. 计算状态值函数曲面 V_k(x) ===
V_x = zeros(size(X));
for i = 1:length(k_range)
    k = k_range(i);
    V_x(i, :) = P(k) * (x_range).^2;  % V_k(x) = x^T P_k x
end

% === 5. 创建控制-时间网格并计算控制值函数 ===
u_range = linspace(-8, 8, 50);     % 控制输入范围
[U, K_u] = meshgrid(u_range, k_range(1:N-1));  % 注意：最后一时刻无控制

% 控制值函数：Q_k(x_k, u) = x_k^T Q x_k + u^T R u + V_{k+1}(x_{k+1})
V_u = zeros(size(U));

for i = 1:size(K_u, 1)  % 遍历时间步
    k = K_u(i, 1);
    for j = 1:size(U, 2)  % 遍历控制输入
        u = U(i, j);
        x_k = x_opt(k);  % 当前状态
        x_next = A * x_k + B * u;  % 下一状态
        V_u(i, j) = x_k' * Q * x_k + u' * R * u + P(k+1) * x_next^2;
    end
end

% === 6. 计算最优控制对应的Q函数值 ===
Q_vals = zeros(1, N-1);
for k = 1:N-1
    x_k = x_opt(k);
    u_k = u_opt(k);
    Q_vals(k) = x_k * Q * x_k + u_k * R * u_k + P(k+1) * (A*x_k + B*u_k)^2;
end

% === 7. 可视化 ===
figure('Color','w', 'Position',[100,100,1200,500]); %[output:48a0bb07]

% 子图1：状态-时间-值函数曲面
subplot(1,2,1); %[output:48a0bb07]
hold on; grid on; view(3); %[output:48a0bb07]

% 绘制状态值函数曲面
surf(X, K, V_x, 'FaceAlpha',0.7, 'EdgeColor','none'); %[output:48a0bb07]
colormap(jet); %[output:48a0bb07]

% 绘制山谷线 (x=0)
plot3(zeros(size(k_range)), k_range, zeros(size(k_range)), 'r-', ... %[output:48a0bb07]
    'LineWidth',3, 'DisplayName','山谷线 (x=0)'); %[output:48a0bb07]

% 标记最优轨迹
for k = 1:N-1
    plot3(x_opt(k), k, P(k)*x_opt(k)^2, 'ro', ... %[output:48a0bb07]
        'MarkerFaceColor','y', 'MarkerSize',8); %[output:48a0bb07]
end

% 连接最优轨迹
plot3(x_opt(1:N-1), 1:N-1, P(1:N-1).*x_opt(1:N-1).^2, 'r--', ... %[output:48a0bb07]
    'LineWidth',1.5, 'DisplayName','最优轨迹'); %[output:48a0bb07]

% 标注
text(x0, 1, P(1)*x0^2+5, sprintf('起点\nx_0=%.1f',x0), ... %[output:48a0bb07]
    'FontSize',10, 'Color','b', 'HorizontalAlignment','center'); %[output:48a0bb07]
text(0, N/2, 0, '山谷线: x=0\n(V_k最小值轨迹)', ... %[output:48a0bb07]
    'FontSize',10, 'BackgroundColor','w', 'HorizontalAlignment','center'); %[output:48a0bb07]

xlabel('状态 x', 'FontWeight','bold'); %[output:48a0bb07]
ylabel('时间步 k', 'FontWeight','bold'); %[output:48a0bb07]
zlabel('值函数 V_k(x)', 'FontWeight','bold'); %[output:48a0bb07]
title('状态空间：V_k(x) = x^TP_kx', 'FontSize',12, 'FontWeight','bold'); %[output:48a0bb07]
colorbar; %[output:48a0bb07]
legend('Location','best'); %[output:48a0bb07]

% 子图2：控制-时间-值函数曲面
subplot(1,2,2); %[output:48a0bb07]
hold on; grid on; view(3); %[output:48a0bb07]

% 绘制控制值函数曲面
surf(U, K_u, V_u, 'FaceAlpha',0.7, 'EdgeColor','none'); %[output:48a0bb07]
colormap(jet); %[output:48a0bb07]

% 绘制最优控制轨迹
for k = 1:N-1
    plot3(u_opt(k), k, Q_vals(k), 'ro', 'MarkerFaceColor','y', 'MarkerSize',8); %[output:48a0bb07]
end

% 连接最优控制轨迹
plot3(u_opt(1:N-1), 1:N-1, Q_vals, 'r--', ... %[output:48a0bb07]
    'LineWidth',1.5, 'DisplayName','最优控制'); %[output:48a0bb07]

% 在每个时间步标记最小值位置
for k = 1:N-1
    % 绘制垂直线：从u轴到Q函数值曲面
    plot3([u_opt(k) u_opt(k)], [k k], [0 Q_vals(k)], 'g:', 'LineWidth',1); %[output:48a0bb07]
end

xlabel('控制输入 u', 'FontWeight','bold'); %[output:48a0bb07]
ylabel('时间步 k', 'FontWeight','bold'); %[output:48a0bb07]
zlabel('Q函数 Q_k(x_k, u)', 'FontWeight','bold'); %[output:48a0bb07]
title('控制空间：Q_k(x_k, u) = x_k^TQx_k + u^TRu + V_{k+1}(x_{k+1})', ... %[output:48a0bb07]
    'FontSize',12, 'FontWeight','bold'); %[output:48a0bb07]
colorbar; %[output:48a0bb07]
legend('Location','best'); %[output:48a0bb07]

% 添加总标题
sgtitle('离散LQR：状态-控制对偶空间可视化', 'FontSize',14, 'FontWeight','bold'); %[output:48a0bb07] %[output:5876ef52]

% === 7. 额外：单独显示控制轨迹和状态轨迹 ===
figure('Color','w', 'Position',[100,100,800,300]); %[output:799c918f]

% 子图1：状态轨迹
subplot(1,2,1); %[output:799c918f]
% 修正：使用stairs绘制状态轨迹
stairs(0:N-1, x_opt(1:N), 'b-', 'LineWidth',2, 'DisplayName','状态轨迹'); %[output:799c918f]
hold on; %[output:799c918f]
% 添加终端状态
plot(N, x_opt(N+1), 'b*', 'MarkerSize',10, 'LineWidth',2, 'DisplayName','终端状态'); %[output:799c918f]
% 标记所有状态点
plot(0:N, x_opt, 'ro', 'MarkerFaceColor','r', 'MarkerSize',6, 'DisplayName','状态点'); %[output:799c918f]
grid on; %[output:799c918f]
xlabel('时间步 k', 'FontWeight','bold'); %[output:799c918f]
ylabel('状态 x_k', 'FontWeight','bold'); %[output:799c918f]
title('最优状态轨迹', 'FontSize',12, 'FontWeight','bold'); %[output:799c918f]
xlim([0, N]); %[output:799c918f]
legend('Location','best'); %[output:799c918f]

% 子图2：控制轨迹
subplot(1,2,2); %[output:799c918f]
% 修正：使用stairs绘制控制序列
stairs(0:N-2, u_opt(1:N-1), 'b-', 'LineWidth',2, 'DisplayName','控制序列'); %[output:799c918f]
hold on; %[output:799c918f]
% 标记所有控制点
plot(0:N-2, u_opt(1:N-1), 'ro', 'MarkerFaceColor','r', 'MarkerSize',6, 'DisplayName','控制点'); %[output:799c918f]
grid on; %[output:799c918f]
xlabel('时间步 k', 'FontWeight','bold'); %[output:799c918f]
ylabel('控制输入 u_k', 'FontWeight','bold'); %[output:799c918f]
title('最优控制序列', 'FontSize',12, 'FontWeight','bold'); %[output:799c918f]
xlim([0, N-1]); %[output:799c918f]
legend('Location','best'); %[output:799c918f]

% 添加网格
grid on; %[output:799c918f]

% 添加总标题
sgtitle('离散LQR最优轨迹', 'FontSize',14, 'FontWeight','bold'); %[output:799c918f]

% === 8. 打印结果 ===
fprintf('=== 离散LQR仿真结果 ===\n'); %[output:8e040da7]
fprintf('系统参数:\n'); %[output:9c7fd5aa]
fprintf('  A = %.2f, B = %.2f, Q = %.2f, R = %.2f\n', A, B, Q, R); %[output:802c6146]
fprintf('  初始状态: x0 = %.2f\n', x0); %[output:4c146f4f]
fprintf('  时间步数: N = %d\n\n', N); %[output:75804377]

fprintf('最优轨迹详情:\n'); %[output:10b8aa7b]
fprintf('时间步  状态 x_k    控制 u_k    控制增益 K_k\n'); %[output:50dcc497]
fprintf('-------------------------------------------------\n'); %[output:03704a35]
for k = 1:N-1 %[output:group:8972c389]
    fprintf('  k=%-2d  %10.4f  %10.4f  %10.4f\n', ... %[output:809f76b3]
        k, x_opt(k), u_opt(k), K_opt(k)); %[output:809f76b3]
end %[output:group:8972c389]
fprintf('  k=%-2d  %10.4f       -               -\n', N, x_opt(N)); %[output:524f4ea2]
fprintf('终端状态 x_%d = %.4f\n\n', N+1, x_opt(N+1)); %[output:1e2a5b18]

% 计算性能指标
J_total = 0;
for k = 1:N
    J_total = J_total + x_opt(k)^2 * Q;  % 状态代价
    if k <= N-1
        J_total = J_total + u_opt(k)^2 * R;  % 控制代价
    end
end
% 添加终端代价
J_total = J_total + x_opt(N+1)^2 * Q;

fprintf('性能指标计算:\n'); %[output:845543e3]
fprintf('  总代价 J = ∑(x_k^T Q x_k + u_k^T R u_k) + x_N^T Q x_N\n'); %[output:903baf14]
fprintf('        = %.4f\n\n', J_total); %[output:4cd57b44]

fprintf('Riccati方程分析:\n'); %[output:21a5090b]
fprintf('  稳态Riccati解: P_∞ = %.6f\n', P(1)); %[output:82de20b5]
fprintf('  稳态控制增益: K_∞ = %.6f\n', K_opt(1)); %[output:00192b1e]

% 分析收敛性
fprintf('\n收敛性分析:\n'); %[output:2b1f46e6]
P_diff = diff(P);
fprintf('  |P_k - P_{k+1}|的最大值: %.6f\n', max(abs(P_diff))); %[output:241927be]
if max(abs(P_diff)) < 1e-4 %[output:group:87c740e4]
    fprintf('  Riccati解在%d步内已收敛到稳态\n', N);
else
    fprintf('  Riccati解尚未完全收敛，建议增加N值\n'); %[output:7b39036d]
end %[output:group:87c740e4]

% 验证最优性条件
fprintf('\n最优性条件验证:\n'); %[output:12d87660]
fprintf('  检查哈密顿-雅可比-贝尔曼方程:\n'); %[output:02511c79]
max_error = 0;
for k = 1:N-1
    % 计算理论最优控制: u* = -(R + B'P_{k+1}B)^{-1}B'P_{k+1}A x_k
    u_theory = -(R + B'*P(k+1)*B) \ (B'*P(k+1)*A) * x_opt(k);
    error = abs(u_theory - u_opt(k));
    max_error = max(max_error, error);
end
fprintf('  控制律计算最大误差: %.6e\n', max_error); %[output:26f508ca]
if max_error < 1e-10 %[output:group:3bb49599]
    fprintf('  ✓ 满足最优性条件\n'); %[output:5c775e87]
else
    fprintf('  ✗ 不满足最优性条件\n');
end %[output:group:3bb49599]

